	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		if el < minLoad { minLoad = el }
		totalLoad += el
	}
	avgLoad := float64(totalLoad) / float64(len(snapshots))
	scores := make(map[string]float64, len(snapshots))
	for _, snap := range snapshots {
		s := prefixScores[snap.ID]
		if s < 0 { s = 0 }
		if s > 1 { s = 1 }
		scores[snap.ID] += s * w0
